anki.css:
.card { font-family: system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif; font-size: 21px; line-height: 1.45; text-align: center; color: #1f1f1f; background: #fafaf8; max-width: 38em; margin: 0 auto; padding: 0.8em; }
.nightMode.card, .night_mode .card { color: #e6e6e6; background: #1e1e1e; }
hr#answer { border: 0; border-top: 1px solid #c8c8c8; margin: 1em 0; }
img { max-width: 100%; height: auto; }
b, strong { font-weight: 650; }
